// Assemble le prompt : mail reçu + historique des réponses précédentes à ce correspondant
const src = $('Entrée sous-workflow').first().json;
const found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);

const ownText = (t) => String(t || '').replace(/\r/g, '')
  .split(/\n(?:>|Le .{5,90} a écrit|De ?:|From:|-----Original|On .{5,90} wrote)/)[0].trim();

const history = found
  .map(j => ({ date: new Date(j.envelope.date || 0), subject: j.envelope.subject || '', text: ownText(j.textContent) }))
  .filter(h => h.text.length >= 30)
  .sort((a, b) => b.date - a.date)
  .slice(0, 3)
  .map((h, n) => `--- Échange ${n + 1} (${h.date.toISOString().slice(0, 10)}, objet : ${h.subject}) ---\n${h.text.slice(0, 700)}`)
  .join('\n\n');

const body = String(src.text || '').trim().slice(0, 4000);
const prompt = [
  'MAIL REÇU',
  `De : ${src.from_name ? src.from_name + ' ' : ''}<${src.from_address}>`,
  `Objet : ${src.subject}`,
  `Date : ${src.date}`,
  `Résumé (assistant de tri) : ${src.resume || ''}`,
  '',
  'Contenu :',
  body || '(message sans texte)',
  '',
  'HISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)',
  history || "(aucun échange précédent trouvé : vouvoie par défaut)",
  '',
  'Rédige le brouillon de réponse.'
].join('\n');

return [{ json: { prompt, historyCount: history ? history.split('--- Échange ').length - 1 : 0 } }];

// Compose un e-mail RFC822 (réponse) à enregistrer dans le dossier Brouillons
const src = $('Entrée sous-workflow').first().json;
const draft = String($input.first().json.text || '').trim();
if (!draft) throw new Error('Brouillon vide renvoyé par le modèle');

const MY = { name: 'Ebanista', addr: 'contact@ebanista.fr' };
const CRLF = '\r\n';
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const isAscii = (s) => /^[\x20-\x7e]*$/.test(s);

// en-tête non ASCII -> mots encodés (RFC 2047), découpés en petits morceaux
const encodeHeader = (s) => {
  if (isAscii(s)) return s;
  const chars = Array.from(s), parts = [];
  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);
  return parts.join(CRLF + ' ');
};
const displayName = (name) => {
  if (!name) return '';
  // nom non ASCII : un seul mot encodé (le découper en plusieurs mots encodés le coupe à l'affichage)
  if (!isAscii(name)) return `=?UTF-8?B?${b64(name)}?=`;
  return /[^\w .'-]/.test(name) ? `"${name.replace(/(["\\])/g, '\\$1')}"` : name;
};

let subject = String(src.subject || '').trim();
while (/^(re|ré)\s*:\s*/i.test(subject)) subject = subject.replace(/^(re|ré)\s*:\s*/i, '');
subject = 'Re: ' + subject;

const origId = src.message_id ? (String(src.message_id).startsWith('<') ? src.message_id : `<${src.message_id}>`) : '';
const when = src.date ? new Date(src.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';
const who = (src.from_name ? src.from_name + ' ' : '') + `<${src.from_address}>`;
const quoted = String(src.text || '').replace(/\r/g, '').trim().slice(0, 3000).split('\n').map(l => '> ' + l).join('\n');
const text = `${draft}\n\n\nLe ${when}, ${who} a écrit :\n${quoted}\n`;

const headers = [
  `From: ${displayName(MY.name)} <${MY.addr}>`,
  `To: ${src.from_name ? displayName(src.from_name) + ' ' : ''}<${src.from_address}>`,
  `Subject: ${encodeHeader(subject)}`,
  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,
  `Message-ID: <draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}@ebanista.fr>`,
  ...(origId ? [`In-Reply-To: ${origId}`, `References: ${origId}`] : []),
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
];
const bodyB64 = b64(text.replace(/\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);

return [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + bodyB64 + CRLF, subject, draftPreview: draft } }];
